const staticData = $getWorkflowStaticData('global');
const raw = $json.choices?.[0]?.message?.content || "";

 let parsed;
 try {
   parsed = JSON.parse(raw);
 } catch (err) {
   throw new Error(`Failed to parse Groq response as JSON: ${err.message} | raw: ${raw.slice(0, 300)}`);
 }

function blocksToHtml(blocks) {
  if (!Array.isArray(blocks)) return String(blocks || "");
  return blocks.map(b => {
    if (typeof b === "string") return `<p>${b}</p>`;
switch (b.type) {
  case "p": return `<p>${b.text}</p>`;
  case "h2": return `<h2>${b.text}</h2>`;
  case "h3": return `<h3>${b.text}</h3>`;
  case "h4": return `<h4>${b.text}</h4>`;
case "stat": return `<p><strong>${b.value || ""}</strong> ${b.label || b.text || ""}</p>`;
case "pullquote": return `<blockquote>${b.text}</blockquote>`;
case "list": return `<ul>${(b.items||[]).map(i=>`<li>${i}</li>`).join("")}</ul>`;
case "callout": return `<div class="callout">${b.text}</div>`;
  default: {
    const stringEntries = Object.entries(b)
      .filter(([k, v]) => k !== "type" && typeof v === "string" && v.trim().length > 0)  // <-- exclude 'type'
      .sort((a, c) => c[1].length - a[1].length);
    if (stringEntries.length === 0) return "";
    if (stringEntries.length === 1) return `<p>${stringEntries[0][1]}</p>`;
    const [, bodyVal] = stringEntries[0];
    const [, headVal] = stringEntries[1];
    if (headVal.length < 80) return `<h2>${headVal}</h2><p>${bodyVal}</p>`;
    return `<p>${bodyVal}</p><p>${headVal}</p>`;
  }
}
  }).join("\n");
}

// Helper to normalize array-or-string fields Groq might return inconsistently
function asArray(val) {
  if (Array.isArray(val)) return val;
  if (typeof val === "string") {
    return val.split(/\r?\n|\|/).map(s => s.trim()).filter(Boolean);
  }
  return [];
}

const upstream = $('Code in JavaScript2').item.json;
const bodyBlocks = parsed.body || parsed.content || parsed.article || parsed.sections || [];

const plainTextWordCount = blocksToHtml(bodyBlocks).replace(/<[^>]+>/g, " ").trim().split(/\s+/).filter(Boolean).length;

return [{
  json: {
    // Existing fields downstream nodes rely on
    title: parsed.headline || upstream.title || "Untitled",
    content: blocksToHtml(bodyBlocks),
    slug: parsed.slug || "",
    section: parsed.section || "compliance",
    kicker: parsed.kicker || "",
    dek: parsed.dek || "",
    byline: parsed.byline || "Shahid Shah",
    articleDate: parsed.date || new Date().toISOString().slice(0, 10),
    dateline: parsed.dateline || "",
    readMinutes: parsed.readMinutes || null,
    categoryId: upstream.categoryId || staticData.currentCategoryId,
    link: upstream.link || null,
    topic: upstream.topic || "CMMC Updates",

    // NEW: companion assets required by the OAT gate node
    altTitles: asArray(parsed.altTitles),
    linkedinPost: parsed.linkedinPost || "",
    newsletterSummary: parsed.newsletterSummary || "",
    suggestedDiagrams: asArray(parsed.suggestedDiagrams),
    followOnIdeas: asArray(parsed.followOnIdeas)
  }
}];

const staticData = $getWorkflowStaticData('global');
const wpResponse = $json; // the WordPress post creation response — not used for article data
const articleData = $('Code in JavaScript1').item.json; // has title, content, and needs followOnIdeas too

// Follow-on ideas tracking
if (!Array.isArray(staticData.pendingFollowOnTopics)) {
  staticData.pendingFollowOnTopics = [];
}
const newIdeas = (articleData.followOnIdeas || [])
  .map(idea => typeof idea === "string" ? idea : idea.title)
  .filter(Boolean);
newIdeas.forEach(title => {
  if (!staticData.pendingFollowOnTopics.includes(title)) {
    staticData.pendingFollowOnTopics.push(title);
  }
});
staticData.pendingFollowOnTopics = staticData.pendingFollowOnTopics.slice(-30);

// Headline tracking
if (!Array.isArray(staticData.recentHeadlines)) {
  staticData.recentHeadlines = [];
}
if (articleData.title) {
  staticData.recentHeadlines.push(articleData.title);
  staticData.recentHeadlines = staticData.recentHeadlines.slice(-15);
}

console.log('Writing recentHeadlines:', staticData.recentHeadlines);
console.log('Writing pendingFollowOnTopics:', staticData.pendingFollowOnTopics);

return { json: wpResponse };

