const items = $input.all();
const staticData = $getWorkflowStaticData('global');

if (!staticData.postedUrls) staticData.postedUrls = [];
if (!staticData.postedTitles) staticData.postedTitles = [];
if (!staticData.postedContentHashes) staticData.postedContentHashes = [];
if (!staticData.oatPassedCount) staticData.oatPassedCount = 0;

// Locked to CMMC only
const cmmcKeywords = [
  "cmmc", "c3pao", "poa&m", "ssp ", "nist sp 800-171", "nist 800-171",
  "nist sp 800-172", "nist 800-172", "scoring methodology", "level 1", "level 2", "level 3",
  "assessment", "certification", "compliance", "cui", "controlled unclassified",
  "dib ", "defense industrial base", "cyberab", "scoping guide"
];

// Word count target for the article body
const MIN_WORDS = 100;
const MAX_WORDS = 200;
// small tolerance since LLM word counts are approximate
const WORD_TOLERANCE = 50;

// Helper: pick the first present field from a list of possible key names
// (handles Groq's field-naming drift across runs)
function pickField(data, keys) {
  for (const k of keys) {
    if (data[k] !== undefined && data[k] !== null && data[k] !== "") return data[k];
  }
  return null;
}

function wordCount(text) {
  const stripped = (text || "").replace(/<[^>]+>/g, " ").trim();
  if (!stripped) return 0;
  return stripped.split(/\s+/).filter(Boolean).length;
}

function asArray(val) {
  if (Array.isArray(val)) return val;
  if (typeof val === "string") {
    // handle newline- or pipe-separated lists if Groq returns a single string
    return val.split(/\r?\n|\|/).map(s => s.trim()).filter(Boolean);
  }
  return [];
}

const passing = [];

for (const item of items) {
  const data = item.json;

  // --- Duplicate checks ---
  if (data.link && staticData.postedUrls.includes(data.link)) {
    console.log(`SKIP (duplicate URL): "${data.title}"`);
    continue;
  }

  const normalizedIncoming = (data.title || "")
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  const isTitleDuplicate = staticData.postedTitles.some(stored => {
    const normalizedStored = stored
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, "")
      .replace(/\s+/g, " ")
      .trim();
    const words = normalizedIncoming.split(" ");
    for (let i = 0; i <= words.length - 6; i++) {
      if (normalizedStored.includes(words.slice(i, i + 6).join(" "))) return true;
    }
    return false;
  });

  if (isTitleDuplicate) {
    console.log(`SKIP (duplicate title): "${data.title}"`);
    continue;
  }

  // --- Content checks ---
  const normalizedContent = (data.content || "")
    .toLowerCase()
    .replace(/<[^>]+>/g, " ")
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!data.title || data.title === "Untitled" || data.title.trim().length < 5) {
    console.log(`SKIP (no title): "${JSON.stringify(data).slice(0, 200)}"`);
    continue;
  }

  if (!data.content || data.content.trim().length < 600) {
    console.log(`SKIP (content too short): "${data.title}"`);
    continue;
  }

  // --- Word count gate (1,000-1,500 words) ---
  const articleWordCount = wordCount(data.content);
  if (articleWordCount < (MIN_WORDS - WORD_TOLERANCE) || articleWordCount > (MAX_WORDS + WORD_TOLERANCE)) {
    console.log(`SKIP (word count ${articleWordCount} outside ${MIN_WORDS}-${MAX_WORDS} range): "${data.title}"`);
    continue;
  }

  // --- Relevance checks ---
  const searchableText = `${data.title} ${data.content} ${data.dek || ""} ${data.topic || ""}`.toLowerCase();
  const isCmmcRelevant = cmmcKeywords.some(kw => searchableText.includes(kw));

  if (!isCmmcRelevant) {
    console.log(`SKIP (not CMMC relevant): "${data.title}"`);
    continue;
  }

  // --- Vendor PR / generic news-report exclusion ---
  // (also screens out "news reporting" phrasing that conflicts with the
  // contrarian/thought-leadership voice)
  const excludedPatterns = [
    "press release", "partnership announcement", "series a", "series b",
    "funding round", "raises $", "announces partnership", "proud to announce",
    "top 10", "game-changer", "revolutionary", "disrupting government",
    "according to a recent report", "in a recent announcement", "sources say",
    "experts agree", "industry leaders say"
  ];
  const isVendorPR = excludedPatterns.some(kw => searchableText.includes(kw));
  if (isVendorPR) {
    console.log(`SKIP (vendor PR / news-report tone): "${data.title}"`);
    continue;
  }

  // --- Required companion assets ---
  // (alt titles, LinkedIn post, newsletter summary, diagrams, follow-on ideas)
  const altTitles = asArray(pickField(data, ["altTitles", "alternativeTitles", "titleOptions", "titles"]));
  if (altTitles.length < 5) {
    console.log(`SKIP (fewer than 5 alternative titles, got ${altTitles.length}): "${data.title}"`);
    continue;
  }

  const linkedinPost = pickField(data, ["linkedinPost", "linkedInPost", "linkedin_post"]);
  if (!linkedinPost || String(linkedinPost).trim().length < 50) {
    console.log(`SKIP (missing/short LinkedIn post): "${data.title}"`);
    continue;
  }

  const newsletterSummary = pickField(data, ["newsletterSummary", "newsletter_summary", "digestSummary"]);
  if (!newsletterSummary || String(newsletterSummary).trim().length < 30) {
    console.log(`SKIP (missing/short newsletter summary): "${data.title}"`);
    continue;
  }

  const suggestedDiagrams = asArray(pickField(data, ["suggestedDiagrams", "diagramIdeas", "diagrams"]));
  if (suggestedDiagrams.length < 1) {
    console.log(`SKIP (no suggested diagrams): "${data.title}"`);
    continue;
  }

  const followOnIdeas = asArray(pickField(data, ["followOnIdeas", "followOnArticles", "relatedArticleIdeas"]));
  if (followOnIdeas.length < 5) {
    console.log(`SKIP (fewer than 5 follow-on article ideas, got ${followOnIdeas.length}): "${data.title}"`);
    continue;
  }

  // --- Passed OAT ---
  console.log(`OAT PASSED [CMMC Updates]: "${data.title}" (${articleWordCount} words)`);

  const subtitleText = data.dek || data.subtitle || data.kicker || "";

  passing.push({
    json: {
      // explicitly set required fields
      title: data.title,
      content: data.content,        // ✅ ensure content is passed
      post_content: data.content,   // ✅ fallback for custom endpoints
      slug: data.slug || "",
      section: data.section || "",
      kicker: data.kicker || "",
      dek: data.dek || "",
      byline: data.byline || "",
      articleDate: data.articleDate || "",
      readMinutes: data.readMinutes || "",
      categoryId: data.categoryId || 52,
      status: data.status || "draft",
      categories: [52], // locked to CMMC Updates
      oat_passed: true,
      oat_section: "CMMC Updates",
      oat_timestamp: new Date().toISOString(),
      oat_word_count: articleWordCount,

      // companion assets carried through for downstream nodes
      // (e.g. a node that posts these to Slack/LinkedIn/newsletter draft)
      altTitles,
      linkedinPost,
      newsletterSummary,
      suggestedDiagrams,
      followOnIdeas,

      meta: {
        ...(data.meta || {}),
        td_post_theme_settings: {
          ...(data.meta?.td_post_theme_settings || {}),
          td_subtitle: subtitleText
        }
      }
    }
  });

  // Update staticData caches
  if (data.link) staticData.postedUrls.push(data.link);
  staticData.postedTitles.push(data.title);
  staticData.postedContentHashes.push(normalizedContent);
  staticData.oatPassedCount++;

  // Trim caches
  if (staticData.postedUrls.length > 300) staticData.postedUrls.shift();
  if (staticData.postedTitles.length > 300) staticData.postedTitles.shift();
  if (staticData.postedContentHashes.length > 300) staticData.postedContentHashes.shift();
}

// --- Final return ---
console.log(`OAT result: ${passing.length} of ${items.length} passed`);

if (passing.length === 0) {
  return items.map(i => {
    const d = i.json;
    const contentLen = (d.content || "").trim().length;
    const normTitle = (d.title || "").toLowerCase().replace(/[^a-z0-9 ]/g, "").replace(/\s+/g, " ").trim();
    const searchable = `${d.title} ${d.content} ${d.dek || ""} ${d.topic || ""}`.toLowerCase();
    return {
      json: {
        debug_failure: true,
        reason: "No items passed — see skip/fail details below",
        title: d.title,
        content: d.content || "",        // ✅ include content in debug
        post_content: d.content || "",   // ✅ fallback in debug
        content_length: contentLen,
        content_preview: (d.content || "").slice(0, 150),
        word_count: wordCount(d.content),
        categoryId: d.categoryId,
        is_cmmc_relevant: cmmcKeywords.some(kw => searchable.includes(kw)),
        is_title_duplicate: staticData.postedTitles.includes(d.title),
        title_word_count: normTitle.split(" ").length,
        alt_titles_count: asArray(pickField(d, ["altTitles", "alternativeTitles", "titleOptions", "titles"])).length,
        has_linkedin_post: !!pickField(d, ["linkedinPost", "linkedInPost", "linkedin_post"]),
        has_newsletter_summary: !!pickField(d, ["newsletterSummary", "newsletter_summary", "digestSummary"]),
        diagram_ideas_count: asArray(pickField(d, ["suggestedDiagrams", "diagramIdeas", "diagrams"])).length,
        follow_on_ideas_count: asArray(pickField(d, ["followOnIdeas", "followOnArticles", "relatedArticleIdeas"])).length
      }
    };
  });
}

return passing;

const staticData = $getWorkflowStaticData('global');
const recentHeadlines = Array.isArray(staticData.recentHeadlines) ? staticData.recentHeadlines : [];
const fixedTopic = "CMMC Updates";
const fixedCategoryId = 52;
const angles = ["Unobvious", "Under the Radar", "Innovative"];
if (staticData.angleIndex === undefined || staticData.angleIndex >= angles.length) {
  staticData.angleIndex = 0;
}
const leadAngle = angles[staticData.angleIndex];
staticData.angleIndex = (staticData.angleIndex + 1) % angles.length;

// "multiPerspectiveSourceAnalysis" is a marker string, not shown to Groq directly —
// when selected it triggers the 3-article branch below instead of the normal single-item output.
const formats = [
  "a news-style article covering a recent CMMC policy or requirement change",
  "an explainer that breaks down a specific CMMC process or requirement step by step",
  "a contrarian piece challenging a common assumption contractors make about CMMC",
  "a data-driven analysis centered on a specific CMMC compliance statistic or trend",
  "a case-study style piece framed around a hypothetical or composite contractor's CMMC journey",
  "a Q&A style article addressing a specific, narrow question about CMMC",
  "multiPerspectiveSourceAnalysis"
];
if (staticData.formatIndex === undefined || staticData.formatIndex >= formats.length) {
  staticData.formatIndex = 0;
}
const selectedFormat = formats[staticData.formatIndex];
staticData.formatIndex = (staticData.formatIndex + 1) % formats.length;

const opsfolioCoveredTopics = [
  "What is CMMC 2.0",
  "CMMC compliance levels overview",
  "CMMC assessment process basics",
  "CMMC certification cost overview"
];
// Recently covered follow-on subjects — used only to steer AWAY from repeats
const recentSubjects = Array.isArray(staticData.pendingFollowOnTopics) ? staticData.pendingFollowOnTopics : [];
const avoidTopics = [...opsfolioCoveredTopics, ...recentSubjects].join("; ");

staticData.currentCategoryId = fixedCategoryId;
staticData.currentTopic = fixedTopic;
staticData.currentFormat = selectedFormat;
staticData.currentAngle = leadAngle;

// --- Pull the incoming source article from the previous node ---
// Adjust these field names if your upstream node (RSS/scrape) uses different keys.
const incoming = $input.item.json || {};
const sourceArticle = {
  title: incoming.title || incoming.articleTitle || "",
  url: incoming.link || incoming.url || incoming.articleUrl || "",
  content: incoming.content || incoming.articleContent || incoming.text || incoming.rawContent || ""
};

const baseJson = {
  title: fixedTopic,
  link: fixedTopic,
  categoryId: fixedCategoryId,
  content: fixedTopic,
  topic: fixedTopic,
  leadAngle: leadAngle,
  avoidTopics: avoidTopics,
  recentHeadlines: recentHeadlines.join(" | ")
};

if (selectedFormat !== "multiPerspectiveSourceAnalysis") {
  return [{
    json: {
      ...baseJson,
      format: selectedFormat
    }
  }];
}

// --- Multi-perspective source-article analysis: emit 3 items, one per article ---
const analysisPreamble = `You are simultaneously a senior federal technology journalist, CISO, CTO, CMMC assessor, software architect, compliance expert, and investigative business writer writing for staging-9980-federalarchitect.wpcomstaging.com.

Your job is NOT to summarize the source article below.

Instead, analyze it deeply and identify:
- What important ideas are missing.
- What assumptions the author makes.
- What engineering lessons are hidden beneath the story.
- What executives should learn.
- What software engineering teams should change.
- What compliance teams should do differently.
- How AI could improve this process.
- What future trends this event signals.

Use the source article only as inspiration, and reference its URL to give credit where credit is due.

Source article title: ${sourceArticle.title}
Source article URL: ${sourceArticle.url}
Source article content: ${sourceArticle.content}`;

const perspectives = [
  {
    perspective: "Executive",
    perspectiveInstructions: "Write for CEOs, CIOs, CTOs, CISOs, Board members, and government contractors. Focus on strategic risk, business impact, and decisions leadership needs to make."
  },
  {
    perspective: "Engineering",
    perspectiveInstructions: "Write for DevSecOps and engineering teams. Focus on evidence automation, secure software development, continuous compliance, AI-assisted engineering, and operational excellence."
  },
  {
    perspective: "Compliance",
    perspectiveInstructions: "Write for compliance and risk teams. Focus on CMMC, NIST 800-171, DIBCAC assessments, False Claims Act implications, evidence generation, and audit readiness."
  }
];

const groupId = `${Date.now()}-multiPerspective`;

return perspectives.map(p => ({
  json: {
    ...baseJson,
    format: `${p.perspective} perspective: ${p.perspectiveInstructions}`,
    perspective: p.perspective,
    multiArticleGroupId: groupId,
    sourceArticle: sourceArticle,
    analysisPrompt: `${analysisPreamble}\n\nThis specific article: ${p.perspectiveInstructions}`
  }
}));
